// Card vault envelope encryption.
// Each card number is encrypted with a fresh data key (AES-256-GCM), and the
// data key is wrapped so only the vault can unwrap it.
//
// Format v2 (written today): the data key is wrapped with a hybrid
// X25519 + ML-KEM-768 (FIPS 203) key encapsulation. Both shared secrets are
// combined with HKDF-SHA-256 into a one-time key-encryption key (KEK), and the
// KEK wraps the data key with AES-256-GCM. An attacker has to break both
// X25519 and ML-KEM-768 to recover the data key.
//
// Format v1 (legacy, read only): envelopes without a `v` field have the data
// key wrapped with RSA-OAEP-2048 (SHA-256). They are still opened so stored
// cards stay readable until the planned batch job re-wraps them as v2. New
// envelopes are never written in v1.
import {
  constants,
  createCipheriv,
  createDecipheriv,
  createPublicKey,
  decapsulate,
  diffieHellman,
  encapsulate,
  generateKeyPairSync,
  hkdfSync,
  privateDecrypt,
  randomBytes,
} from 'node:crypto';

export const ENVELOPE_VERSION = 2;
const KEK_INFO = 'demo-payments card-vault data-key wrap v2 (X25519+ML-KEM-768)';
const CONTENT_AAD = Buffer.from('demo-payments card-vault envelope v2');
const WRAP_AAD = Buffer.from('demo-payments card-vault data-key v2');

// Returns the vault's hybrid key pair. Each half is a pair of KeyObjects:
// { publicKey: { x25519, mlkem }, privateKey: { x25519, mlkem } }.
export function generateVaultKeys() {
  const x25519 = generateKeyPairSync('x25519');
  const mlkem = generateKeyPairSync('ml-kem-768');
  return {
    publicKey: { x25519: x25519.publicKey, mlkem: mlkem.publicKey },
    privateKey: { x25519: x25519.privateKey, mlkem: mlkem.privateKey },
  };
}

// Legacy RSA key pair, kept only so tests can produce v1 envelopes. Do not use
// it to seal new cards.
export function generateLegacyRsaVaultKeys() {
  return generateKeyPairSync('rsa', { modulusLength: 2048 });
}

function spki(key) {
  return key.export({ type: 'spki', format: 'der' });
}

// KEK = HKDF-SHA-256(
//   ikm  = ss_mlkem || ss_x25519 || len-prefixed(ephemeral X25519 pub,
//          ML-KEM ciphertext, vault X25519 pub),
//   salt = empty, info = purpose label, L = 32).
// The transcript goes into the IKM (as in X-Wing) because Node caps HKDF info
// at 1024 bytes and the ML-KEM-768 ciphertext alone is 1088 bytes.
function deriveKek(mlkemSecret, x25519Secret, ephemeralPub, kemCiphertext, vaultX25519Pub) {
  const parts = [mlkemSecret, x25519Secret];
  for (const p of [ephemeralPub, kemCiphertext, vaultX25519Pub]) {
    const len = Buffer.alloc(4);
    len.writeUInt32BE(p.length);
    parts.push(len, p);
  }
  return Buffer.from(hkdfSync('sha256', Buffer.concat(parts), Buffer.alloc(0), KEK_INFO, 32));
}

function gcmEncrypt(key, plaintext, aad) {
  const iv = randomBytes(12);
  const cipher = createCipheriv('aes-256-gcm', key, iv);
  cipher.setAAD(aad);
  const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  return { iv, ciphertext, tag: cipher.getAuthTag() };
}

function gcmDecrypt(key, iv, ciphertext, tag, aad) {
  const decipher = createDecipheriv('aes-256-gcm', key, iv);
  if (aad) decipher.setAAD(aad);
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
}

const b64 = (buf) => buf.toString('base64');
const unb64 = (s) => Buffer.from(s, 'base64');

export function sealCard(cardNumber, vaultPublicKey) {
  if (!vaultPublicKey?.x25519 || !vaultPublicKey?.mlkem) {
    throw new TypeError('sealCard needs the hybrid vault public key { x25519, mlkem }');
  }
  const dataKey = randomBytes(32);
  const content = gcmEncrypt(dataKey, Buffer.from(cardNumber, 'utf8'), CONTENT_AAD);

  const ephemeral = generateKeyPairSync('x25519');
  const x25519Secret = diffieHellman({ privateKey: ephemeral.privateKey, publicKey: vaultPublicKey.x25519 });
  const { sharedKey: mlkemSecret, ciphertext: kemCiphertext } = encapsulate(vaultPublicKey.mlkem);
  const ephemeralPub = spki(ephemeral.publicKey);
  const kek = deriveKek(mlkemSecret, x25519Secret, ephemeralPub, kemCiphertext, spki(vaultPublicKey.x25519));
  const wrap = gcmEncrypt(kek, dataKey, WRAP_AAD);

  return {
    v: ENVELOPE_VERSION,
    ephemeralKey: b64(ephemeralPub),
    kemCiphertext: b64(kemCiphertext),
    wrapIv: b64(wrap.iv),
    wrapTag: b64(wrap.tag),
    wrappedKey: b64(wrap.ciphertext),
    iv: b64(content.iv),
    tag: b64(content.tag),
    ciphertext: b64(content.ciphertext),
  };
}

// vaultPrivateKey: { x25519, mlkem } for v2 envelopes. To read legacy v1
// envelopes, also pass { rsa } (or the RSA private key itself).
export function openCard(envelope, vaultPrivateKey) {
  if (envelope.v === undefined) return openLegacyCard(envelope, vaultPrivateKey);
  if (envelope.v !== ENVELOPE_VERSION) {
    throw new Error(`unsupported card envelope version: ${envelope.v}`);
  }
  if (!vaultPrivateKey?.x25519 || !vaultPrivateKey?.mlkem) {
    throw new TypeError('openCard needs the hybrid vault private key { x25519, mlkem } for v2 envelopes');
  }
  const ephemeralPub = unb64(envelope.ephemeralKey);
  const kemCiphertext = unb64(envelope.kemCiphertext);
  const x25519Secret = diffieHellman({
    privateKey: vaultPrivateKey.x25519,
    publicKey: createPublicKey({ key: ephemeralPub, format: 'der', type: 'spki' }),
  });
  const mlkemSecret = decapsulate(vaultPrivateKey.mlkem, kemCiphertext);
  const vaultX25519Pub = spki(createPublicKey(vaultPrivateKey.x25519));
  const kek = deriveKek(mlkemSecret, x25519Secret, ephemeralPub, kemCiphertext, vaultX25519Pub);
  const dataKey = gcmDecrypt(kek, unb64(envelope.wrapIv), unb64(envelope.wrappedKey), unb64(envelope.wrapTag), WRAP_AAD);
  return gcmDecrypt(dataKey, unb64(envelope.iv), unb64(envelope.ciphertext), unb64(envelope.tag), CONTENT_AAD)
    .toString('utf8');
}

// Legacy v1 read path (RSA-OAEP-2048). Remove once every stored envelope has
// been re-wrapped as v2.
function openLegacyCard(envelope, vaultPrivateKey) {
  const rsaKey = vaultPrivateKey?.rsa ?? vaultPrivateKey;
  if (!rsaKey || rsaKey.x25519 || rsaKey.mlkem) {
    throw new TypeError('legacy v1 card envelope needs the vault RSA private key ({ rsa })');
  }
  const dataKey = privateDecrypt(
    { key: rsaKey, padding: constants.RSA_PKCS1_OAEP_PADDING, oaepHash: 'sha256' },
    unb64(envelope.wrappedKey),
  );
  return gcmDecrypt(dataKey, unb64(envelope.iv), unb64(envelope.ciphertext), unb64(envelope.tag)).toString('utf8');
}

// Re-wrap helper for the batch job: open any envelope (v1 or v2) and seal it
// again as v2 under the hybrid public key.
export function rewrapCard(envelope, vaultPrivateKey, vaultPublicKey) {
  return sealCard(openCard(envelope, vaultPrivateKey), vaultPublicKey);
}

