// Signed webhooks.
// Payment events are pushed to merchants. Every event is dual-signed over the
// same body bytes:
//   X-Signature        ECDSA P-256 / SHA-256, base64 (unchanged, legacy)
//   X-Signature-MLDSA  ML-DSA-65 (FIPS 204), base64 (post-quantum)
// Older merchant SDKs read only X-Signature and keep working. Upgraded
// verifiers pass the ML-DSA public key and then require both signatures.
//
// Sunset for X-Signature (ECDSA): no fixed date. About 40 merchants still
// verify with an old SDK that only understands ECDSA P-256 and cannot be made
// to upgrade this quarter. Remove the ECDSA header only once every merchant
// verifies X-Signature-MLDSA (see infra/DEPLOY.md).
import { generateKeyPairSync, sign, verify } from 'node:crypto';

export const ECDSA_HEADER = 'X-Signature';
export const MLDSA_HEADER = 'X-Signature-MLDSA';

// publicKey/privateKey stay the ECDSA P-256 pair so existing callers keep
// working; the ML-DSA-65 pair is added under `mldsa`.
export function generateWebhookKeys() {
  const ecdsa = generateKeyPairSync('ec', { namedCurve: 'prime256v1' });
  const mldsa = generateKeyPairSync('ml-dsa-65');
  return { publicKey: ecdsa.publicKey, privateKey: ecdsa.privateKey, mldsa };
}

// mldsaPrivateKey is optional only so legacy callers keep compiling; the
// service should always pass it.
export function signEvent(event, privateKey, mldsaPrivateKey) {
  const body = JSON.stringify(event);
  const data = Buffer.from(body);
  const headers = { [ECDSA_HEADER]: sign('sha256', data, privateKey).toString('base64') };
  if (mldsaPrivateKey) {
    headers[MLDSA_HEADER] = sign(null, data, mldsaPrivateKey).toString('base64');
  }
  return { body, headers };
}

function verifySafely(fn) {
  try {
    return fn();
  } catch {
    return false;
  }
}

// Without mldsaPublicKey: ECDSA only (legacy verifier behaviour).
// With mldsaPublicKey: both signatures must verify, and a missing ML-DSA
// header fails, so it cannot be stripped to downgrade to ECDSA alone.
export function verifyEvent(body, headers, publicKey, mldsaPublicKey) {
  const data = Buffer.from(body);
  const ecdsaSig = Buffer.from(headers[ECDSA_HEADER] ?? '', 'base64');
  const ecdsaOk = verifySafely(() => verify('sha256', data, publicKey, ecdsaSig));
  if (!mldsaPublicKey) return ecdsaOk;
  const mldsaHeader = headers[MLDSA_HEADER];
  if (!mldsaHeader) return false;
  const mldsaSig = Buffer.from(mldsaHeader, 'base64');
  const mldsaOk = verifySafely(() => verify(null, data, mldsaPublicKey, mldsaSig));
  return ecdsaOk && mldsaOk;
}

